<?php
require_once __DIR__ . '/includes/functions.php'; require_login(); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{if(($_POST['action']??'')==='save'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$contact=trim($_POST['contact_person']??'');$phone=trim($_POST['phone']??'');$email=trim($_POST['email']??'');if($name==='')throw new RuntimeException();if($id){$s=$pdo->prepare('UPDATE suppliers SET name=?,contact_person=?,phone=?,email=? WHERE id=?');$s->execute([$name,$contact,$phone,$email,$id]);}else{$s=$pdo->prepare('INSERT INTO suppliers(name,contact_person,phone,email) VALUES(?,?,?,?)');$s->execute([$name,$contact,$phone,$email]);}flash('Supplier saved.');}elseif(($_POST['action']??'')==='delete'){$s=$pdo->prepare('DELETE FROM suppliers WHERE id=?');$s->execute([(int)$_POST['id']]);flash('Supplier deleted.');}}catch(Throwable $e){flash('Could not save supplier. Check required fields and product references.','error');}redirect('suppliers.php');}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM suppliers WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$rows=$pdo->query('SELECT s.*,COUNT(p.id) product_count FROM suppliers s LEFT JOIN products p ON p.supplier_id=s.id GROUP BY s.id ORDER BY s.name')->fetchAll();$page_title='Suppliers';require 'includes/header.php'; ?>
<?php if(isset($_GET['add'])||$edit): ?><section class="panel form-panel"><h3><?= $edit?'Edit':'Add' ?> supplier</h3><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label>Supplier name<input name="name" required value="<?= e($edit['name']??'') ?>"></label><label>Contact person<input name="contact_person" value="<?= e($edit['contact_person']??'') ?>"></label><label>Phone<input name="phone" value="<?= e($edit['phone']??'') ?>"></label><label>Email<input type="email" name="email" value="<?= e($edit['email']??'') ?>"></label><div class="form-buttons"><button class="btn primary">Save supplier</button><a class="btn secondary" href="suppliers.php">Cancel</a></div></form></section><?php endif; ?>
<div class="page-actions"><span class="muted">Maintain supplier contact details.</span><a class="btn primary" href="suppliers.php?add=1">＋ Add supplier</a></div>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Contact</th><th>Phone</th><th>Email</th><th>Products</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td class="strong"><?= e($r['name']) ?></td><td><?= e($r['contact_person']) ?></td><td><?= e($r['phone']) ?></td><td><?= e($r['email']) ?></td><td><?= (int)$r['product_count'] ?></td><td class="actions"><a href="suppliers.php?edit=<?= $r['id'] ?>">Edit</a><form method="post" data-confirm="Delete this supplier?"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= $r['id'] ?>"><button class="link danger">Delete</button></form></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="empty">No suppliers yet.</td></tr><?php endif; ?></tbody></table></div></section>
<?php require 'includes/footer.php'; ?>
